#include <array>
#include <iostream>
#include <limits>
#include <span>
#include <variant>

enum class SumError { too_many, negative, overflow };
using SumResult = std::variant<long long, SumError>;

SumResult checked_sum_cents(std::span<const long long> values) {
    if (values.size() > 1000) {
        return SumError::too_many;
    }
    long long total = 0;
    for (const auto value : values) {
        if (value < 0) {
            return SumError::negative;
        }
        if (value > std::numeric_limits<long long>::max() - total) {
            return SumError::overflow;
        }
        total += value;
    }
    return total;
}

void display_sum(const SumResult& result) {
    if (const auto* value = std::get_if<long long>(&result)) {
        std::cout << *value << '\n';
    } else {
        switch (std::get<SumError>(result)) {
            case SumError::too_many: std::cout << "too-many\n"; break;
            case SumError::negative: std::cout << "negative\n"; break;
            case SumError::overflow: std::cout << "overflow\n"; break;
        }
    }
}

int main() {
    const std::array<long long, 3> good{1, 2, 3};
    const std::array<long long, 0> empty{};
    const std::array<long long, 2> negative{1, -1};
    const std::array<long long, 2> overflow{std::numeric_limits<long long>::max(), 1};
    display_sum(checked_sum_cents(good));
    display_sum(checked_sum_cents(empty));
    display_sum(checked_sum_cents(negative));
    display_sum(checked_sum_cents(overflow));
}

