#include <variant>

enum class SumError { too_many, negative, overflow };
using SumResult = std::variant<long long, SumError>;

SumResult checked_sum_cents(std::span<const long long> values) {
    if (values.size() > 1000) {
        return SumError::too_many;
    }
    long long total = 0;
    for (const auto value : values) {
        if (value < 0) {
            return SumError::negative;
        }
        if (value > std::numeric_limits<long long>::max() - total) {
            return SumError::overflow;
        }
        total += value;
    }
    return total;
}

void display_sum(const SumResult& result) {
    if (const auto* value = std::get_if<long long>(&result)) {
        std::cout << *value << '\n';
    } else {
        switch (std::get<SumError>(result)) {
            case SumError::too_many: std::cout << "too-many\n"; break;
