#include <stdexcept>

long long require_sum_cents(std::span<const long long> values) {
    const auto result = checked_sum_cents(values);
    if (const auto* value = std::get_if<long long>(&result)) {
        return *value;
    }
    switch (std::get<SumError>(result)) {
        case SumError::too_many: throw std::invalid_argument("too many amounts");
        case SumError::negative: throw std::invalid_argument("negative amount");
        case SumError::overflow: throw std::overflow_error("total out of range");
    }
    throw std::logic_error("unexpected sum error");
}

int main() {
    const std::array<long long, 1> zero{0};
    std::cout << require_sum_cents(zero) << '\n';
    const std::array<long long, 1> bad{-1};
    try {
        static_cast<void>(require_sum_cents(bad));
    } catch (const std::invalid_argument&) {
        std::cout << "input rejected\n";
    }
    const std::array<long long, 2> huge{std::numeric_limits<long long>::max(), 1};
    try {
        static_cast<void>(require_sum_cents(huge));
    } catch (const std::overflow_error&) {
        std::cout << "range rejected\n";
    }
}

#include <iostream>
#include <stdexcept>
#include <utility>

struct Ledger {
    int cents = 0; // invariant: 0 <= cents <= 100
    void basic(bool fail) {
        cents = 0; // valid, but discards the old value
        if (fail) throw std::runtime_error("injected");
        cents = 20;
    }
    void strong(bool fail) {
        int candidate = 20;
        if (fail) throw std::runtime_error("injected");
        cents = candidate; // nonthrowing commit for this scalar
    }
    void reset() noexcept { cents = 0; }
};
struct Guard {
    int& live;
    explicit Guard(int& n) : live(n) { ++live; }
    ~Guard() noexcept { --live; }
};
int main() {
    int cases = 0;
    for (int old = 0; old <= 100; ++old) {
        Ledger a{old}, b{old};
        try { a.basic(true); } catch (const std::runtime_error&) {}
        try { b.strong(true); } catch (const std::runtime_error&) {}
        if (a.cents != 0 || b.cents != old) return 1;
        a.basic(false); b.strong(false);
        if (a.cents != 20 || b.cents != 20) return 2;
        a.reset();
        if (a.cents != 0) return 3;
        ++cases;
    }
    int live = 0;
    try { Guard g(live); throw std::runtime_error("unwind"); }
    catch (const std::runtime_error&) {}
    if (live != 0) return 4;
    static_assert(noexcept(std::declval<Ledger&>().reset()));
    static_assert(!noexcept(std::declval<Ledger&>().strong(false)));
    std::cout << cases << " guarantee cases; live=" << live << '\n';
}

#include <charconv>
#include <iostream>
#include <limits>
#include <optional>
#include <span>
#include <string_view>
#include <system_error>
#include <variant>
#if __has_include(<expected>)
#include <expected>
#endif
#if defined(__cpp_lib_expected) && __cpp_lib_expected >= 202202L
#define QF_NATIVE_EXPECTED 1
#else
#define QF_NATIVE_EXPECTED 0
#endif
struct ParseError { std::error_code code; };
#if QF_NATIVE_EXPECTED
using Result = std::expected<int, ParseError>;
Result bad(std::errc ec) { return std::unexpected(ParseError{std::make_error_code(ec)}); }
bool ok(const Result& r) { return r.has_value(); }
int value(const Result& r) { return r.value(); }
std::error_code error(const Result& r) { return r.error().code; }
#else
using Result = std::variant<int, ParseError>;
Result bad(std::errc ec) { return ParseError{std::make_error_code(ec)}; }
bool ok(const Result& r) { return std::holds_alternative<int>(r); }
int value(const Result& r) { return std::get<int>(r); }
std::error_code error(const Result& r) { return std::get<ParseError>(r).code; }
#endif
// Exact decimal nonnegative integer, optional leading +, no whitespace.
Result parse_cents(std::string_view s) {
    if (s.empty()) return bad(std::errc::invalid_argument);
    if (s.front() == '+') s.remove_prefix(1);
    if (s.empty() || s.front() < '0' || s.front() > '9')
        return bad(std::errc::invalid_argument);
    int n = 0;
    const auto r = std::from_chars(s.data(), s.data() + s.size(), n);
    if (r.ec != std::errc{}) return bad(r.ec);
    if (r.ptr != s.data() + s.size()) return bad(std::errc::invalid_argument);
    return n;
}
std::optional<int> first_positive(std::span<const int> xs) {
    for (int x : xs) if (x > 0) return x;
    return std::nullopt;
}
int main() {
    const char* good[] = {"0", "+0", "7", "0012", "2147483647"};
    const int wanted[] = {0, 0, 7, 12, 2147483647};
    // This lesson's fixtures deliberately require int to represent this bound.
    static_assert(std::numeric_limits<int>::max() >= 2147483647);
    int checked = 0;
    for (int i = 0; i < 5; ++i) {
        const auto r = parse_cents(good[i]);
        if (!ok(r) || value(r) != wanted[i]) return 1;
        ++checked;
    }
    for (const char* s : {"", "+", "-1", " 1", "1x", "+-1"}) {
        const auto r = parse_cents(s);
        if (ok(r) || error(r) != std::errc::invalid_argument) return 2;
        ++checked;
    }
    const auto huge = parse_cents("999999999999999999999999999999999999999999");
    if (ok(huge) || error(huge) != std::errc::result_out_of_range) return 3;
    const int xs[] = {0, -2, 7};
    if (first_positive(xs) != 7 || first_positive(std::span<const int>{})) return 4;
    const auto a = std::make_error_code(std::errc::invalid_argument);
    if (a.category() != std::generic_category()) return 5;
    std::cout << checked + 1 << " parse cases; first=" << *first_positive(xs) << '\n';
    std::cout << "native_expected=" << QF_NATIVE_EXPECTED << '\n';
}
